def largest_smallest_integers(numbers_list):
    """
    This function takes a list of numbers as input and returns a tuple containing the largest negative and smallest positive integers found in the list.

    Parameters:
    - numbers_list: A list of integers.

    Returns:
    - A tuple (largest_negative, smallest_positive) where 'largest_negative' is the largest integer less than zero in the list, and 'smallest_positive' is the smallest integer greater than zero in the list. If no such integers exist, their respective positions in the tuple will be None.
    """

    # Initialize variables to store the largest and smallest values found
    largest_negative = None
    smallest_positive = None

    # Iterate over the list to find the largest and smallest values
    for number in numbers_list:
        if number < 0:
            if largest_negative is None or number > largest_negative:
                largest_negative = number
        elif number > 0:
            if smallest_positive is None or number < smallest_positive:
                smallest_positive = number

    # Return the result as a tuple (largest_negative, smallest_positive)
    return (largest_negative, smallest_positive)

def any_int(a, b, c):
    # Check if all inputs are integers
    if not all(isinstance(i, int) for i in [a, b, c]):
        return False

    # Check if the sum of any two numbers equals the third number
    return a + b == c or b + c == a or c + a == b

def square_perimeter(side_length):
    # The perimeter of a square is calculated as 4 times the side length
    return 4 * side_length

def even_Power_Sum(n):
    total_sum = 0  # Initialize the total sum variable

    # Loop through each number from 1 to n
    for i in range(1, n + 1):
        # Check if the number is even
        if i % 2 == 0:
            # Square the number and add it to the total sum
            total_sum += i ** 4

    # Return the total sum of squares of even numbers
    return total_sum

def check_tuplex(tuple_data, target_value):
    # Use the 'in' keyword to determine if the target value exists within the tuple
    return target_value in tuple_data

def Find_Max_Length(nested_list):
    # Initialize a counter to keep track of the maximum depth
    max_depth = 0

    # Iterate through each element in the nested list
    for item in nested_list:
        # If the item is a list itself, recursively call the function with this sublist
        if isinstance(item, list):
            current_depth = 1 + Find_Max_Length(item)

            # Update the maximum depth if the current depth is greater than the previous maximum
            if current_depth > max_depth:
                max_depth = current_depth

    # Return the maximum depth found
    return max_depth

def get_pairs_count(numbers, target_sum):
    pair_count = 0

    # Iterate through each element in the list
    for index in range(len(numbers)):
        # Calculate the complement needed to reach the target sum
        complement = target_sum - numbers[index]

        # Check if the complement exists in the remaining part of the list
        if complement in numbers[index + 1:]:
            pair_count += 1

    return pair_count
